import triton
import triton.language as tl
from triton.runtime import driver

# asin polynomial constants (degree-3 minimax fit of the cephes-style identity
# asin(|x|) = a + a*z*P(z), z=x*x for |x|<=0.5 else 0.5*(1-|x|), a=sqrt(z)).
# Verified within tolerance for fp32/fp16/bf16 including near |x|=1.
_PIO2 = 1.5707963267948966
_c0 = 0.16660854011233464
_c1 = 0.07718246747617585
_c2 = 0.026913546774612745
_c3 = 0.07548313160737156


@triton.jit
def _asin_kernel(
    x_ptr,
    out_ptr,
    N,
    BLOCK: tl.constexpr,
    PIO2: tl.constexpr,
    c0: tl.constexpr,
    c1: tl.constexpr,
    c2: tl.constexpr,
    c3: tl.constexpr,
):
    pid = tl.program_id(0)
    nprog = tl.num_programs(0)
    step = nprog * BLOCK
    for start in range(pid * BLOCK, N, step):
        offs = start + tl.arange(0, BLOCK)
        mask = offs < N
        x = tl.load(x_ptr + offs, mask=mask, other=0.0)
        xf = x.to(tl.float32)
        ax = tl.abs(xf)
        hi = ax > 0.5
        z = tl.where(hi, 0.5 * (1.0 - ax), ax * ax)
        # a = sqrt(z) is valid in BOTH branches: in the low branch z = ax*ax so
        # sqrt(z) == ax, so no separate select is needed. For |x|>1 the high
        # branch has z<0 -> sqrt NaN, which propagates and reproduces
        # torch.asin's out-of-domain NaN.
        a = tl.sqrt(z)
        poly = (((c3 * z + c2) * z + c1) * z + c0) * z * a + a
        res = tl.where(hi, PIO2 - (poly + poly), poly)
        res = tl.where(xf < 0.0, -res, res)
        tl.store(out_ptr + offs, res.to(x.dtype), mask=mask)


_NUM_VECTORCORE = None


def _num_vectorcore():
    global _NUM_VECTORCORE
    if _NUM_VECTORCORE is None:
        try:
            props = driver.active.utils.get_device_properties(
                torch.npu.current_device()
            )
            _NUM_VECTORCORE = int(props["num_vectorcore"])
        except Exception:
            _NUM_VECTORCORE = 40
    return _NUM_VECTORCORE


